package bench

// Corpora for the log track.
//
// PROVENANCE, STATED UP FRONT: these are SYNTHETIC. They are generated by the
// code below rather than captured from a production host, for two reasons —
// real logs carry hostnames, paths and usernames that have no business in a
// public repository, and a committed multi-megabyte capture makes the repo
// worse for everyone who clones it. The shapes are drawn from real output:
// systemd restart lines, compiler progress, an access log, a verbose Go test
// run.
//
// This is the suite's LARGEST WEAKNESS and the report says so. A generator
// written by the same person who benefits from the result can flatter the
// result. Two things are done about it: the generators are short enough to
// audit in one sitting, and the suite deliberately includes corpora the tool
// does NOT win on (see the adversarial scenarios). Neither fully removes the
// concern. A reader who does not trust a synthetic corpus should run the same
// arms over their own logs — that is why the arms are exported.
//
// Everything here is deterministic: no rand, no clock, no environment. The
// timestamps are fixed strings, so the same checkout always yields the same
// bytes and the same report.

import (
	"fmt"
	"strings"
)

// restartLoopLog is a service caught in a restart loop, buried in ordinary
// boot chatter. The climbing counter is the case exact-duplicate dedup cannot
// touch: no two of those lines are byte-identical.
//
// The counter ends at 614.
func restartLoopLog() string {
	var b strings.Builder
	for i := 0; i < 1200; i++ {
		fmt.Fprintf(&b, "Aug 21 03:24:%02d ice-server kernel: [%6d.%06d] audit: type=1400 op=apparmor_load profile=unconfined name=snap.core.hook.configure pid=%d\n",
			i%60, 100000+i, (i*7919)%1000000, 4000+i)
	}
	for i := 599; i <= 614; i++ {
		fmt.Fprintf(&b, "Aug 21 03:26:59 ice-server systemd[2158]: light-edge.service: Scheduled restart job, restart counter is at %d.\n", i)
		fmt.Fprintf(&b, "Aug 21 03:26:59 ice-server systemd[2158]: Stopped light-edge.service - Light Edge Daemon.\n")
		fmt.Fprintf(&b, "Aug 21 03:26:59 ice-server systemd[2158]: Started light-edge.service - Light Edge Daemon.\n")
	}
	for i := 0; i < 1200; i++ {
		fmt.Fprintf(&b, "Aug 21 03:28:%02d ice-server kernel: [%6d.%06d] audit: type=1400 op=apparmor_load profile=unconfined name=snap.core.hook.configure pid=%d\n",
			i%60, 200000+i, (i*104729)%1000000, 9000+i)
	}
	return b.String()
}

// buildFailureLog is the shape every developer knows: a long, uniform progress
// stream ending in the one line that matters. The verdict is a singleton by
// nature, which is precisely what a design that suppresses singletons would
// delete.
func buildFailureLog() string {
	var b strings.Builder
	for i := 0; i < 500; i++ {
		fmt.Fprintf(&b, "compiling module %d of 500\n", i)
	}
	b.WriteString("internal/remote/transport.go:127:14: cannot use outStream.Text (variable of type string) as int value in assignment\n")
	b.WriteString("BUILD FAILED\n")
	return b.String()
}

// accessLog is a needle-in-a-haystack corpus: 20,000 requests, nearly all of
// them fine, and three that are not. The two 500s share a path.
func accessLog() string {
	var b strings.Builder
	paths := []string{"/api/status", "/api/session", "/static/app.js", "/api/plan", "/healthz"}
	for i := 0; i < 20000; i++ {
		path := paths[i%len(paths)]
		status := 200
		switch {
		case i%997 == 0:
			status = 304
		case i%1499 == 0:
			status = 404
		}
		if i == 8421 || i == 15903 {
			path, status = "/api/plan/settle", 500
		}
		fmt.Fprintf(&b, "10.0.%d.%d - - [21/Aug/2026:03:%02d:%02d +0000] \"GET %s HTTP/1.1\" %d %d \"-\" \"light-agent/0.4.0\"\n",
			(i/256)%256, i%256, (i/60)%60, i%60, path, status, 128+(i*13)%4096)
	}
	return b.String()
}

// verboseTestLog is a passing suite with exactly one failure in it — the
// everyday case for an agent asked "did the tests pass, and if not what
// broke?".
func verboseTestLog() string {
	var b strings.Builder
	packages := []string{"bash", "filetool", "logs", "mcp", "ops", "remote", "security", "telemetry", "terse"}
	for _, pkg := range packages {
		for i := 0; i < 40; i++ {
			name := fmt.Sprintf("Test%sBehaviour%d", strings.ToUpper(pkg[:1])+pkg[1:], i)
			fmt.Fprintf(&b, "=== RUN   %s\n", name)
			fmt.Fprintf(&b, "--- PASS: %s (0.0%ds)\n", name, i%10)
		}
	}
	b.WriteString("=== RUN   TestSpillRecoveryPointerResolves\n")
	b.WriteString("    deliver_test.go:88: spill pointer did not resolve: record expired\n")
	b.WriteString("--- FAIL: TestSpillRecoveryPointerResolves (0.01s)\n")
	b.WriteString("FAIL\tgithub.com/icediceice/light-tools/internal/logs\t0.312s\n")
	return b.String()
}

// shortStatusLog is ADVERSARIAL. It sits under the pass-through floor
// (internal/logs/analyze.go: defaultMinLines 40, defaultMinBytes 4000 — output
// below BOTH is returned exactly as given), so light-tools must hand it back
// byte-for-byte and the row must report parity.
//
// If this scenario ever shows a saving, compaction has started touching output
// that was already legible and the floor has regressed. The row is a canary,
// not a filler.
func shortStatusLog() string {
	return strings.Join([]string{
		"● light-edge.service - Light Edge Daemon",
		"     Loaded: loaded (/etc/systemd/system/light-edge.service; enabled)",
		"     Active: active (running) since Fri 2026-08-21 03:28:04 UTC; 2h 11min ago",
		"   Main PID: 41207 (light-edge)",
		"      Tasks: 12 (limit: 38158)",
		"     Memory: 48.2M",
		"        CPU: 1min 4.203s",
		"     CGroup: /system.slice/light-edge.service",
		"             └─41207 /usr/local/bin/light-edge --config /etc/light/edge.toml",
		"",
		"Aug 21 03:28:04 ice-server systemd[1]: Started light-edge.service.",
		"Aug 21 03:28:04 ice-server light-edge[41207]: listening on 127.0.0.1:8737",
		"Aug 21 03:28:05 ice-server light-edge[41207]: hub connection established",
	}, "\n") + "\n"
}
